import{Lt as e,Vt as t,Z as n,_t as r,bt as i,mt as a,vt as o,yt as s}from"./chunks/framework.CsLlEPF4.js";var c=JSON.parse(`{"title":"从备份中恢复 Zotero 数据","description":"","frontmatter":{"title":"从备份中恢复 Zotero 数据","date":"2025-04-13T00:00:00.000Z"},"headers":[],"relativePath":"user-guide/faqs/restore-data-from-backup.md","filePath":"wiki/user-guide/faqs/restore-data-from-backup.md"}`),l={name:`user-guide/faqs/restore-data-from-backup.md`},u={class:`table-of-contents`},d={href:`#使用-zotero-同步恢复数据`},f={href:`#从完整手动备份恢复数据`},p={href:`#从数据库自动备份恢复数据`},m={href:`#从备份恢复并覆盖已同步的更改`},h={href:`#降级-zotero-时从升级备份恢复数据`},g={id:`使用-zotero-同步恢复数据`,tabindex:`-1`},_={id:`从完整手动备份恢复数据`,tabindex:`-1`},v={id:`从数据库自动备份恢复数据`,tabindex:`-1`},y={id:`从备份恢复并覆盖已同步的更改`,tabindex:`-1`},b={id:`降级-zotero-时从升级备份恢复数据`,tabindex:`-1`};function x(n,c,l,x,S,C){let w=t(`Badge`),T=t(`NolebaseGitContributors`),E=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[c[23]||=a(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidefaqsrestore-data-from-backup.md for this page in Markdown format`,-1),c[24]||=a(`h1`,{id:`从备份中恢复-zotero-数据`,tabindex:`-1`},[s(`从备份中恢复 Zotero 数据 `),a(`a`,{class:`header-anchor`,href:`#从备份中恢复-zotero-数据`,"aria-label":`Permalink to “从备份中恢复 Zotero 数据”`},`​`)],-1),c[25]||=a(`p`,null,`本教程将指导您如何从各种备份中恢复 Zotero 数据，包括同步备份、手动备份、自动备份等多种情况。`,-1),a(`nav`,u,[a(`ul`,null,[a(`li`,null,[a(`a`,d,[c[0]||=s(`使用 Zotero 同步恢复数据`,-1),i(w,{text:`初级`})])]),a(`li`,null,[c[3]||=a(`a`,{href:`#从本地备份中恢复数据`},`从本地备份中恢复数据`,-1),a(`ul`,null,[a(`li`,null,[a(`a`,f,[c[1]||=s(`从完整手动备份恢复数据`,-1),i(w,{text:`中级`})])]),a(`li`,null,[a(`a`,p,[c[2]||=s(`从数据库自动备份恢复数据`,-1),i(w,{text:`中级`})])])])]),a(`li`,null,[a(`a`,m,[c[4]||=s(`从备份恢复并覆盖已同步的更改`,-1),i(w,{text:`中级`})])]),a(`li`,null,[a(`a`,h,[c[5]||=s(`降级 Zotero 时从升级备份恢复数据`,-1),i(w,{text:`高级`})])]),c[6]||=a(`li`,null,[a(`a`,{href:`#找不到-zotero-数据的解决方案`},`找不到 Zotero 数据的解决方案`)],-1),c[7]||=a(`li`,null,[a(`a`,{href:`#仍然无法解决`},`仍然无法解决？`)],-1)])]),c[26]||=o(`<div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>在进行任何恢复操作前，请确保 Zotero 已经关闭。在 Zotero 运行时修改数据文件可能会导致数据损坏。</p></div><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>在对数据文件夹进行任何操作之前，都建议您先对数据文件夹进行备份，以备不时之需。备份的步骤详见：<a href="./../backup">Zotero 备份教程</a>。</p></div><div class="danger custom-block"><p class="custom-block-title custom-block-title-default">危险</p><p>无论你选择何种同步方案，也无论基于何种原因，切勿将 Zotero 的 <code>数据存储位置/Data Directory</code> 自定义为任何网盘的同步文件夹中（包括 iCloud），也切勿使用任何网盘/同步盘的备份功能直接同步/备份这一目录!（包括但不限于直接使用坚果云的官方客户端直接同步备份这一文件夹）</p><p>这样做在某些情况下可能会导致你的 Zotero 数据库损坏，带来严重的问题！官方对于这一问题的说明见这两篇文章：</p><ul><li><a href="https://www.zotero.org/support/sync#alternative_syncing_solutions" target="_blank" rel="noreferrer">How can I access my library from multiple computers?</a></li><li><a href="https://www.zotero.org/support/kb/data_directory_in_cloud_storage_folder" target="_blank" rel="noreferrer">Can I store my Zotero data directory in a cloud storage folder?</a></li></ul><p>如果您已经将 Zotero 数据文件夹直接同步到网盘中，请您做好<a href="./../backup#手动备份">备份</a>，根据 <a href="./../faqs/custom-data-directory">自定义数据文件夹</a> 的教程将数据文件夹迁移到本地的其他位置，且确保未使用任何工具直接同步这一数据文件夹。</p></div>`,3),a(`h2`,g,[c[8]||=s(`使用 Zotero 同步恢复数据`,-1),i(w,{text:`初级`}),c[9]||=s(),c[10]||=a(`a`,{class:`header-anchor`,href:`#使用-zotero-同步恢复数据`,"aria-label":`Permalink to “使用 Zotero 同步恢复数据”`},`​`,-1)]),c[27]||=o(`<p>如果您更换了新设备，或重新安装了系统（本地库为空），且之前正确配置了 <a href="./../sync">Zotero 数据和文件同步</a> 功能并进行了完整的同步，您可以通过同步从在线库恢复您的数据。</p><ol><li><p><strong>验证在线库数据完整性</strong></p><p>首先访问 <a href="https://www.zotero.org/user/login" target="_blank" rel="noreferrer">Zotero 官网</a> 登录您的账户，然后点击页面顶部的 <code>Web Library</code> 进入在线文献库，确认在线库中的数据是否完整且正确。</p><details class="details custom-block"><summary>如果您使用「WebDAV 同步」或「Attanger/ZotMoov + 同步盘」方案同步附件...</summary><p>如果您使用了「WebDAV 同步」或「Attanger/ZotMoov + 同步盘」方案同步附件，由于附件未同步在 Zotero 官方存储空间，您会在在线库中看到附件的文件名，但无法下载和查看附件，这是正常的。</p><p>您可能需要前往 WebDAV 网盘或同步盘服务商的网页端检查附件是否完整。一般来说，您可以通过网盘中附件存储文件夹占用的空间大小来粗略判断附件同步是否完整。</p><ul><li><p><strong>如果您使用的是 WebDAV 同步</strong>：</p><p>你可以检查 WebDAV 网盘中 <code>zotero</code> 文件夹中 <code>zip</code> 压缩包的数量，每个 <code>zip</code> 中会存放一个附件文件。通常来说，<code>zip</code> 应与 Zotero 中存储的各类附件的总数一致。</p><p>您还可以将比较 WebDAV 网盘中 <code>zotero</code> 文件夹的大小与 Zotero 数据目录中 <code>storage</code> 文件夹的大小进行比较，来判断附件同步是否完整。由于 WebDAV 同步时会将附件压缩成 <code>zip</code> 压缩包，实际占用空间可能略小于 Zotero 数据目录中 <code>storage</code> 文件夹的大小。</p></li><li><p><strong>如果您使用的是 Attanger/Zotmoov + 同步盘</strong>：</p><p>您可以直接检查个文件夹中文件的数量，来判断附件是否齐全。</p></li></ul></details></li><li><p><strong>设置同步</strong></p><p>设置 Zotero 的 <a href="./../sync#数据的同步">数据同步</a> 和 <a href="./../sync#文件的同步">文件同步</a>，操作步骤详见：<a href="./../sync">Zotero 同步</a>。</p></li><li><p><strong>开始同步</strong></p><p>点击 Zotero 界面上的「同步」按钮，Zotero 将从服务器下载您的库。</p></li></ol><div class="info custom-block"><p class="custom-block-title custom-block-title-default">信息</p><p>Zotero 只同步明确的删除操作，因此仅同步一个空库不会覆盖服务器数据，除非您手动删除了条目。</p></div><details class="details custom-block"><summary>如果您电脑上的本地 Zotero 数据库中有内容...</summary><p>如果您的本地 Zotero 库有内容，但想用在线库中的数据覆盖它：</p><ol><li>关闭 Zotero。</li><li>将旧的数据库复制到其他地方备份，以备不时之需。</li><li>删除旧 Zotero 数据目录中的所有文件和文件夹，只保留一个空的数据目录文件夹。（如果您已将旧数据目录文件夹剪切到其他地方，您也可以在原位置新建一个同名文件夹）。</li><li>重新打开 Zotero 并设置同步。操作步骤详见：<a href="./../sync">Zotero 同步</a>。</li><li>开始同步。</li></ol></details><h2 id="从本地备份中恢复数据" tabindex="-1">从本地备份中恢复数据 <a class="header-anchor" href="#从本地备份中恢复数据" aria-label="Permalink to “从本地备份中恢复数据”">​</a></h2>`,5),a(`h3`,_,[c[11]||=s(`从完整手动备份恢复数据`,-1),i(w,{text:`中级`}),c[12]||=s(),c[13]||=a(`a`,{class:`header-anchor`,href:`#从完整手动备份恢复数据`,"aria-label":`Permalink to “从完整手动备份恢复数据”`},`​`,-1)]),c[28]||=o(`<p>如果您有 Zotero 数据目录的手动 <a href="./../backup">备份</a>，可以用它替换当前的数据目录来恢复您的库。</p><ol><li><p><strong>暂时禁用同步</strong></p><p>如果您之前设置了同步，请在 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>同步</code> 中，取消选中 <code>自动同步</code> 选项。这样可以防止 Zotero 在操作过程中自动同步。</p></li><li><p><strong>查看当前数据目录位置</strong></p><p>打开 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>高级</code> → <code>文件和文件夹</code> ，记下 <code>数据存储位置</code> 的路径（默认是您的用户文件夹中的 <code>Zotero</code> 目录）。</p></li><li><p><strong>打开数据目录</strong></p><p>点击 <code>打开数据文件夹</code> 按钮，打开当前数据目录（目录中包含 <code>zotero.sqlite</code> 等文件和 <code>storage</code> 等子目录）。</p></li><li><p><strong>备份当前数据目录</strong></p><p>关闭 Zotero，进入数据目录的上级文件夹，将当前数据目录重命名为 <code>Zotero-Old</code>。</p></li><li><p><strong>替换为备份数据</strong></p><p>将您的备份数据目录复制到原来的位置（例如，复制到重命名前的 <code>Zotero</code> 位置，并将新复制过来的目录重命名为 <code>Zotero</code>）。</p></li><li><p><strong>重启 Zotero 并处理同步</strong></p><p>重新启动 Zotero，您应该能看到备份版本的库。如果不需要的更改已经同步，请参照下面 <a href="#从备份恢复并覆盖已同步的更改">从备份恢复并覆盖已同步的更改</a> 中的方法处理。</p></li><li><p><strong>重新启用同步</strong></p><p>确认恢复成功后，在 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>同步</code> 中，重新选中 <code>自动同步</code> 选项，启用自动同步。恢复成功后，您可以删除 <code>Zotero-Old</code> 文件夹，直到确认恢复的数据无误。</p></li></ol>`,2),a(`h3`,v,[c[14]||=s(`从数据库自动备份恢复数据`,-1),i(w,{text:`中级`}),c[15]||=s(),c[16]||=a(`a`,{class:`header-anchor`,href:`#从数据库自动备份恢复数据`,"aria-label":`Permalink to “从数据库自动备份恢复数据”`},`​`,-1)]),c[29]||=o(`<p>如果您在使用 Zotero 时犯了错误（例如，意外删除大量条目），可以尝试恢复到最近的自动备份。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">信息</p><p>自动备份只包含数据库（文献条目信息、笔记、附件、标签、分类），不包含附件文件。</p></div><ol><li><p><strong>暂时禁用同步</strong></p><p>如果您之前设置了同步，请在 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>同步</code> 中，取消选中 <code>自动同步</code> 选项。这样可以防止 Zotero 在操作过程中自动同步。</p></li><li><p><strong>查找自动备份文件</strong></p><p>打开您的 Zotero 数据目录，找到里面所有文件名开头为 <code>zotero.sqlite</code> 且后缀名为 <code>.bak</code> 的文件（如：<code>zotero.sqlite.bak</code>）。这些文件是 Zotero 的自动备份文君，文件的修改时间可能有助于确定哪个文件包含您要恢复的数据。建议先将这些 <code>.bak</code> 文件复制到其他位置备份一下，以备不时之需。</p></li><li><p><strong>替换数据库文件</strong></p><p>关闭 Zotero。在数据目录中，将 <code>zotero.sqlite</code> 重命名为 <code>zotero.sqlite.old</code>，然后将选定的 <code>.bak</code> 文件之一重命名为 <code>zotero.sqlite</code>。</p></li><li><p><strong>重启 Zotero 并处理同步</strong></p><p>重新启动 Zotero，您应该能看到备份版本的库。如果不需要的更改已经同步，请参照下面 <a href="#从备份恢复并覆盖已同步的更改">从备份恢复并覆盖已同步的更改</a> 中的方法处理。</p></li><li><p><strong>重新启用同步</strong></p><p>确认恢复成功后，在 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>同步</code> 中，重新选中 <code>自动同步</code> 选项，启用自动同步。保留 <code>zotero.sqlite.old</code> 和您的 <code>.bak</code> 文件备份，直到确认所有数据都完好无损。</p></li></ol>`,3),a(`h2`,y,[c[17]||=s(`从备份恢复并覆盖已同步的更改`,-1),i(w,{text:`中级`}),c[18]||=s(),c[19]||=a(`a`,{class:`header-anchor`,href:`#从备份恢复并覆盖已同步的更改`,"aria-label":`Permalink to “从备份恢复并覆盖已同步的更改”`},`​`,-1)]),c[30]||=o(`<p>如果您不小心在 Zotero 库中进行了不需要的更改并已同步到在线库，您可以使用本地备份恢复数据并覆盖在线更改。</p><ol><li><p><strong>暂时禁用自动同步</strong></p><p>在 Zotero 的 <code>编辑</code> → <code>设置</code> → <code>同步</code> 中，取消选中 <code>自动同步</code> 选项。这样可以防止 Zotero 在操作过程中自动同步。</p></li><li><p><strong>从备份恢复数据</strong></p><p>按照前文 <a href="#从本地备份中恢复数据">从本地备份中恢复数据</a> 中的步骤恢复本地数据库。</p></li><li><p><strong>处理潜在的同步冲突</strong></p><p>恢复数据后，如果直接同步，在线库中的更新数据会替换您刚恢复的数据。根据情况选择以下方法之一：</p><ul><li><p><strong>恢复少量删除的条目或笔记</strong>：右键点击并选择「创建条目副本」创建副本，这样同步后新副本会保留。</p></li><li><p><strong>恢复删除的分类</strong>：重复创建一个新的分类，并将条目从旧分类拖到新分类。同步时，旧分类将被删除，但新分类会保留。</p></li><li><p><strong>恢复大量更改</strong>：使用「替换在线库」功能强制 Zotero 上传本地库版本，覆盖之前同步的更改。这需要在 Zotero 中点击 <code>编辑</code> → <code>设置</code> → <code>同步</code>，然后在 <code>重置</code> 中点击 <code>显示重置选项</code> 按钮，然后在「重置」界面中选中 <code>替换在线文献库</code>，最后点击 <code>重置...</code> 按钮。请注意，这将使用本地数据强制覆盖在线库中的所有数据。</p></li></ul></li><li><p><strong>恢复自动同步</strong></p><p>确认恢复成功后，重新启用「自动同步」选项。</p></li></ol>`,2),a(`h2`,b,[c[20]||=s(`降级 Zotero 时从升级备份恢复数据`,-1),i(w,{text:`高级`}),c[21]||=s(),c[22]||=a(`a`,{class:`header-anchor`,href:`#降级-zotero-时从升级备份恢复数据`,"aria-label":`Permalink to “降级 Zotero 时从升级备份恢复数据”`},`​`,-1)]),c[31]||=o(`<p>当您升级到新版本的 Zotero 时，系统会自动备份您的数据库。如果需要降级到低版本 Zotero，可以使用这些备份。</p><details class="details custom-block"><summary>如何降级 Zotero 并恢复数据</summary><ol><li><p><strong>查找升级备份文件</strong></p><p>打开您的 Zotero 数据目录，升级备份通常是数据目录中编号最高的 <code>zotero.sqlite.[数字].bak</code> 文件。</p></li><li><p><strong>备份当前数据目录</strong></p><p>在进行任何更改前，建议备份整个 Zotero 数据目录。备份教程详见：<a href="./../backup">Zotero 备份教程</a>。</p></li><li><p><strong>替换数据库文件</strong></p><p>安装旧版 Zotero，关闭程序，用 <code>zotero.sqlite.[最高编号].bak</code> 替换数据目录中的 <code>zotero.sqlite</code>，然后重启 Zotero。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>如果您尝试在旧版 Zotero 中打开升级后的数据库，Zotero 会显示错误。请关闭 Zotero 并按上述方法替换 <code>.sqlite</code> 文件。</p></div></li><li><p><strong>同步更新</strong></p><p>如果您使用了同步功能，Zotero 将从在线库中同步自上次使用旧数据库以来的所有更改。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>如果您没有使用同步功能，可能需要将数据库升级后添加的条目导出为 Zotero RDF 格式，然后再导入到早期版本中。按「添加日期」排序您的库可能有助于找到这些条目。</p></div></li></ol></details><h2 id="找不到-zotero-数据的解决方案" tabindex="-1">找不到 Zotero 数据的解决方案 <a class="header-anchor" href="#找不到-zotero-数据的解决方案" aria-label="Permalink to “找不到 Zotero 数据的解决方案”">​</a></h2><p>如果打开 Zotero 发现库为空或缺少大量数据，可能有几种原因：</p><ol><li><p><strong>数据库文件损坏或丢失</strong></p><p>可能是 <code>zotero.sqlite</code> 文件被意外删除或损坏。检查数据目录中是否有较大的 <code>zotero.sqlite.bak</code> 文件或其他备份。</p></li><li><p><strong>Zotero 查找数据的位置错误</strong></p><p>Zotero 可能在错误的位置查找数据。检查「编辑」→「设置」→「高级」→「文件和文件夹」中的数据目录路径是否正确。</p></li></ol><p>如果尝试以上方法后仍无法找到您的数据，可能需要：搜索计算机上的其他位置，寻找包含 <code>zotero.sqlite</code> 的其他文件夹。在找到合适的备份文件后，参照 <a href="#从本地备份中恢复数据">从本地备份中恢复数据</a> 的步骤进行恢复。</p><h2 id="仍然无法解决" tabindex="-1">仍然无法解决？ <a class="header-anchor" href="#仍然无法解决" aria-label="Permalink to “仍然无法解决？”">​</a></h2><p>如果上面的步骤均无法解决您的问题，您可以阅读官方文档：<a href="https://www.zotero.org/support/zotero_data#restoring_your_zotero_data_from_a_backup" target="_blank" rel="noreferrer">Restoring Your Zotero Data From a Backup - Zotero Documentation</a>，了解更多细节和解决方案。</p><p>如果您确实无法成功恢复数据，您可以前往 <a href="https://forums.zotero.org/" target="_blank" rel="noreferrer">Zotero 官方论坛</a> 发帖提问寻求帮助。</p>`,9),i(T),i(E)])}var S=n(l,[[`render`,x]]);export{c as __pageData,S as default};